<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;Auth::requireLogin();if(!Auth::can('SUBSCRIPTION_REVIEW_QUEUE_VIEW')&&!Auth::can('PAYMENT_VIEW_FINANCE')){http_response_code(403);exit('Subscription visibility permission required.');}$data=SubscriptionEligibilityService::administrativeOverview();$prices=['GOLD'=>35000,'PREMIUM'=>55000,'PLATINUM'=>100500];$pageTitle='Subscription Plans';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><span class="eyebrow dark">Read-only subscription visibility</span><h1>Subscription plans</h1><p>Operations and Finance can view available plans and see which Carrier selected each plan. Subscription choices are made by Carriers.</p></div><div><?php if(Auth::can('SUBSCRIPTION_REVIEW_QUEUE_VIEW')):?><a class="button secondary" href="<?=h(\App\Support\Url::to('operations/subscriptions.php'))?>">Review pending transfers</a><?php endif;?><span class="badge"><?=h(count($data['subscribers']))?> records</span></div></div><?php if(Auth::can('SUBSCRIPTION_REVIEW_QUEUE_VIEW')):?><div class="notice">Automatic paid activation will require a hosted payment gateway and a verified server-to-server callback. Until that integration exists, pending transfers retain the existing Operations verification control.</div><?php endif;?><div class="plan-grid"><?php foreach($data['plans']as$p):$code=strtoupper($p['plan_code']);?><article class="plan-card plan-<?=h(strtolower($code))?>"><span class="plan-kicker"><?=h($code)?></span><h2><?=h($p['plan_name'])?></h2><p class="plan-price">TSh <?=h(number_format((float)($prices[$code]??0),0))?></p><ul class="plan-features"><li><?=h($p['max_trucks']??'Unlimited')?> trucks</li><li><?=h($p['max_drivers']??'Unlimited')?> drivers</li><li>Read-only plan information</li></ul></article><?php endforeach;?></div><div class="card table-wrap" style="margin-top:18px" tabindex="0" aria-label="Scrollable Carrier subscriptions table"><table style="min-width:1080px"><thead><tr><th>Carrier</th><th>Plan</th><th>State</th><th>Requested</th><th>Starts</th><th>Ends</th><th>Payment recorded</th></tr></thead><tbody><?php foreach($data['subscribers']as$r):?><tr><td><?=h($r['owner_company_name']?:$r['owner_user_name'])?></td><td><strong><?=h($r['plan_name'])?></strong></td><td><span class="status-pill status-<?=h($r['subscription_state'])?>"><?=h($r['subscription_state'])?></span></td><td class="timestamp"><?=h($r['requested_at']?:'—')?></td><td class="timestamp"><?=h($r['start_at']?:'Awaiting activation')?></td><td class="timestamp"><?=h($r['end_at']?:'—')?></td><td><?=h($r['payment_confirmed_at']?'Yes':'No')?></td></tr><?php endforeach;if(!$data['subscribers']):?><tr><td colspan="7" class="muted">No subscription records.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
